// The integer half of base58: `b58encode_int` and `b58decode_int`.
//
// All arithmetic is done with BigInt so values are unbounded, matching Python
// ints. Values are carried as octet arrays / strings rather than any binary
// buffer type.

import { PyValueError } from '../pyerrors.mjs';
import { PyBytes } from '../pybytes.mjs';
import { strRepr } from '../pyrepr.mjs';
import { pyRstrip } from '../pystr.mjs';
import { BITCOIN_ALPHABET, BASE, buildDigitMap } from './alphabet.mjs';
import { encodeAscii } from './scrub.mjs';

/**
 * Python's `divmod` for integers: the quotient floors toward negative infinity
 * and the remainder takes the sign of the divisor. BigInt's own `/` truncates
 * and `%` follows the dividend, so both need correcting.
 */
function pyDivMod(a, b) {
  let quotient = a / b;
  let remainder = a % b;

  if (remainder !== 0n && remainder < 0n !== b < 0n) {
    quotient -= 1n;
    remainder += b;
  }

  return [quotient, remainder];
}

/**
 * `b58encode_int(i)` — encode an integer to a base58 byte string.
 *
 * Zero maps to the alphabet's first character ('1') because of the library's
 * `default_one` behaviour, not because of positional arithmetic.
 *
 * Note: the reference implementation loops on `while i:` using floored divmod,
 * so a negative input never converges — divmod(-1, 58) is (-1, 57) forever.
 * The port keeps the same arithmetic, and therefore the same non-termination,
 * rather than inventing behaviour the original does not have.
 *
 * @param {bigint} i
 * @returns {PyBytes}
 */
export function b58encodeInt(i, { defaultOne = true, alphabet = BITCOIN_ALPHABET } = {}) {
  if (i === 0n && defaultOne) {
    return PyBytes.fromLatin1(alphabet.slice(0, 1));
  }

  const digits = [];
  let value = i;

  while (value !== 0n) {
    const [quotient, index] = pyDivMod(value, BigInt(alphabet.length));
    digits.push(alphabet.charCodeAt(Number(index)));
    value = quotient;
  }

  digits.reverse();
  return new PyBytes(digits);
}

const DIGIT_MAP = buildDigitMap(BITCOIN_ALPHABET);

/**
 * `b58decode_int(v)` — decode a base58 string to an integer.
 *
 * The reference library right-strips the input first (the alphabet contains no
 * space, so trailing whitespace is considered padding), then encodes it as
 * ASCII, then folds the digits. Order matters: trailing whitespace is dropped
 * before the ASCII check, and leading or interior whitespace survives to be
 * reported as an invalid character.
 *
 * @param {string} v
 * @returns {bigint}
 */
export function b58decodeInt(v, { alphabet = BITCOIN_ALPHABET } = {}) {
  const stripped = alphabet.includes(' ') ? v : pyRstrip(v);
  const octets = encodeAscii(stripped);

  const base = BigInt(alphabet.length);
  let decimal = 0n;

  for (const octet of octets) {
    const digit = DIGIT_MAP.get(octet);
    if (digit === undefined) {
      // Python formats this with {!r}, so control characters arrive escaped
      // and a literal quote flips the surrounding quote style.
      const error = new PyValueError(`Invalid character ${strRepr(String.fromCharCode(octet))}`);
      error.pyFrames = ['File "base58/__init__.py", line 104, in b58decode_int'];
      throw error;
    }
    decimal = decimal * base + BigInt(digit);
  }

  return decimal;
}

export { BASE, BITCOIN_ALPHABET };
// Port of base58's `scrub_input`: a str argument is encoded with the *ascii*
// codec before decoding, so any character above U+007F raises
// UnicodeEncodeError rather than being treated as an invalid base58 digit.

import { PyUnicodeEncodeError } from '../pyerrors.mjs';
import { escapeCodePoint } from '../pyrepr.mjs';
import { codePoints } from '../pystr.mjs';

/**
 * Encode a str to ASCII octets. On failure, reproduces CPython's message,
 * which reports the maximal run of consecutive non-encodable characters and
 * its code-point position(s).
 *
 * @returns {number[]} octet values
 */
export function encodeAscii(text) {
  const chars = codePoints(text);

  const start = chars.findIndex((ch) => ch.codePointAt(0) > 0x7f);
  if (start !== -1) {
    let end = start;
    while (end + 1 < chars.length && chars[end + 1].codePointAt(0) > 0x7f) end++;

    const run = chars.slice(start, end + 1);
    const escaped = run.map((ch) => escapeCodePoint(ch.codePointAt(0))).join('');
    const noun = run.length === 1 ? 'character' : 'characters';
    const where = run.length === 1 ? `position ${start}` : `position ${start}-${end}`;

    const error = new PyUnicodeEncodeError(
      `'ascii' codec can't encode ${noun} '${escaped}' in ${where}: ordinal not in range(128)`,
    );
    error.pyFrames = [
      'File "base58/__init__.py", line 94, in b58decode_int',
      'File "base58/__init__.py", line 30, in scrub_input',
    ];
    throw error;
  }

  return chars.map((ch) => ch.codePointAt(0));
}
// The Bitcoin base58 alphabet: the 62 alphanumerics minus the four glyphs that
// are easy to confuse by eye — '0', 'O', 'I' and 'l'.

export const BITCOIN_ALPHABET =
  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

export const BASE = BITCOIN_ALPHABET.length; // 58

/** Digit value of an alphabet character, or undefined when not a member. */
export function buildDigitMap(alphabet = BITCOIN_ALPHABET) {
  const map = new Map();
  for (let i = 0; i < alphabet.length; i++) {
    map.set(alphabet.charCodeAt(i), i);
  }
  return map;
}
// Public surface of the base58 port, mirroring the names the Python module
// exposes so the entry point reads like the original.

export { BITCOIN_ALPHABET, BASE } from './alphabet.mjs';
export { b58encodeInt as b58encode_int, b58decodeInt as b58decode_int } from './int_codec.mjs';
export { b58encodeInt, b58decodeInt } from './int_codec.mjs';
export { encodeAscii } from './scrub.mjs';

// Python string helpers. Python strings are sequences of code points, so every
// routine here works on code-point arrays (`[...s]`) rather than UTF-16 units —
// that keeps positions and lengths aligned with what CPython reports.

import { isPyStrWhitespace } from './pyunicode.mjs';

/** Split a string into its code points, the way Python iterates a str. */
export function codePoints(s) {
  return [...s];
}

/** `str.rstrip()` with no argument: drop trailing `str.isspace()` characters. */
export function pyRstrip(s) {
  const chars = codePoints(s);
  let end = chars.length;
  while (end > 0 && isPyStrWhitespace(chars[end - 1])) end--;
  return chars.slice(0, end).join('');
}

/** `str.strip()` with no argument. */
export function pyStrip(s) {
  const chars = codePoints(s);
  let start = 0;
  let end = chars.length;
  while (start < end && isPyStrWhitespace(chars[start])) start++;
  while (end > start && isPyStrWhitespace(chars[end - 1])) end--;
  return chars.slice(start, end).join('');
}
