// Unicode character-classification primitives that mirror the exact predicates
// CPython relies on. Two *different* whitespace notions matter here, and the
// reference binary distinguishes them:
//
//   * int(str) folds only characters with the Unicode White_Space property.
//   * str.rstrip() also folds U+001C..U+001F (the ASCII separator controls),
//     which str.isspace() reports as whitespace but White_Space does not.
//
// Keeping them apart is what makes `--a '\x1c10'` fail while `--c '5Q\x1c'`
// succeeds, matching the reference binary.

const RE_WHITE_SPACE = /^\p{White_Space}$/u;
const RE_ND = /^\p{Nd}$/u;

// Everything Python treats as unprintable for repr(): the Other and the
// line/paragraph/space separator categories. Plain U+0020 is the one Zs
// character Python still prints literally.
const RE_NONPRINTABLE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/** Characters with the Unicode White_Space property — the set int() folds. */
export function isUnicodeWhitespace(ch) {
  return RE_WHITE_SPACE.test(ch);
}

/**
 * The set `str.isspace()` reports, i.e. White_Space plus the four ASCII
 * separator controls. This is what `str.strip()`/`rstrip()` remove.
 */
export function isPyStrWhitespace(ch) {
  if (RE_WHITE_SPACE.test(ch)) return true;
  const cp = ch.codePointAt(0);
  return cp >= 0x1c && cp <= 0x1f;
}

/** The ASCII-only whitespace `Py_ISSPACE` accepts during numeric scanning. */
export function isAsciiWhitespace(ch) {
  return ch === ' ' || ch === '\t' || ch === '\n' || ch === '\v' || ch === '\f' || ch === '\r';
}

function isDecimalDigitCodePoint(cp) {
  return cp >= 0 && cp <= 0x10ffff && RE_ND.test(String.fromCodePoint(cp));
}

const digitValueCache = new Map();

/**
 * Numeric value of any Unicode decimal digit (General_Category=Nd), or -1.
 *
 * Nd code points always arrive as complete 0-9 decades, but decades can be
 * directly adjacent (U+1D7CE..U+1D7FF packs five of them back to back). So we
 * walk down to the start of the whole contiguous Nd block and take the offset
 * modulo ten rather than assuming the run is only ten long.
 */
export function decimalDigitValue(cp) {
  const cached = digitValueCache.get(cp);
  if (cached !== undefined) return cached;

  let value = -1;
  if (isDecimalDigitCodePoint(cp)) {
    let blockStart = cp;
    while (blockStart > 0 && isDecimalDigitCodePoint(blockStart - 1)) blockStart--;
    value = (cp - blockStart) % 10;
  }

  digitValueCache.set(cp, value);
  return value;
}

/** Whether repr() may emit this character literally instead of escaping it. */
export function isPrintable(ch) {
  if (ch === ' ') return true;
  return !RE_NONPRINTABLE.test(ch);
}

