// Batch 2: float-precision boundary values, seeded random shapes, extra long runs.
import { writeFileSync } from 'node:fs';

const AB = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const out = [];
const emit = (desc, value) =>
  out.push(`${desc}\t${Buffer.from(value, 'utf8').toString('base64')}`);

// Encode a BigInt to base58 so we can build strings with a known target value.
// (Generator-side only; the reference binary remains the oracle.)
const enc = (n) => {
  if (n === 0n) return '1';
  let s = '';
  while (n > 0n) { s = AB[Number(n % 58n)] + s; n /= 58n; }
  return s;
};

// ---- values straddling 2**53 and other float cliffs
const marks = [
  ['2p53-2', (1n << 53n) - 2n], ['2p53-1', (1n << 53n) - 1n], ['2p53', 1n << 53n],
  ['2p53+1', (1n << 53n) + 1n], ['2p53+2', (1n << 53n) + 2n], ['2p53+3', (1n << 53n) + 3n],
  ['2p53x2', (1n << 54n)], ['2p53x2+1', (1n << 54n) + 1n],
  ['2p31', 1n << 31n], ['2p32', 1n << 32n], ['2p32+1', (1n << 32n) + 1n],
  ['2p62', 1n << 62n], ['2p63-1', (1n << 63n) - 1n], ['2p63', 1n << 63n],
  ['2p64-1', (1n << 64n) - 1n], ['2p64', 1n << 64n], ['2p64+1', (1n << 64n) + 1n],
  ['2p127', 1n << 127n], ['2p128-1', (1n << 128n) - 1n],
  ['2p256', 1n << 256n], ['2p512+7', (1n << 512n) + 7n],
  ['9007199254740993', 9007199254740993n],
  ['1e17+1', 100000000000000001n],
  ['58p9', 58n ** 9n], ['58p10', 58n ** 10n], ['58p10-1', 58n ** 10n - 1n],
  ['58p20', 58n ** 20n], ['58p20+57', 58n ** 20n + 57n],
  ['maxsafe-ish', 4503599627370497n],
];
for (const [nm, v] of marks) {
  emit(`fp-${nm}`, enc(v));
  emit(`fp-${nm}-lead1`, '111' + enc(v)); // leading zeros must not change the value
